{
  "root_cause": "Focus does not move to the first input field when the dialog opens because the focus trap delays initial focus via a setTimeout, leaving focus on the triggering element.",
  "repair_strategy": "Disable the delayInitialFocus option when creating the focus trap so that initial focus is applied synchronously after the dialog is shown.",
  "edits": [
    {
      "path": "index.html",
      "sha256": "85fb0980102bd0ea76fa350b8e2df6695a5bf878b5526a6a22d84ca1b8547611",
      "before": "const trap = createFocusTrap('#address-dialog', { onDeactivate: () => { backdrop.hidden = true; } });",
      "after": "const trap = createFocusTrap('#address-dialog', { onDeactivate: () => { backdrop.hidden = true; }, delayInitialFocus: false });"
    }
  ],
  "expected_accessibility_effect": "Keyboard users will receive focus on the first usable field (#street) when the address dialog opens, meeting focus order expectations.",
  "functional_risks": [
    "Setting focus synchronously could, in rare cases, occur before the dialog is fully rendered or before assistive technologies have announced it; however the dialog is already present in the DOM and only its hidden attribute is toggled, making this risk minimal."
  ],
  "verification_requirements": [
    "After pressing Enter on the #open button, focus must be on the #street input.",
    "Pressing Tab from #street should move focus to the #save button.",
    "Pressing Enter on #save should close the dialog and update the status field with the entered address."
  ]
}
